new=r'''const JS_EXTENSIONS = new Set(['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs', '.mts', '.cts']);
const PYTHON_EXTENSIONS = new Set(['.py', '.ipynb']);

const stripComments = (content) =>
  content
    .replace(/(?<![^\s;{}(),])\/\*[\s\S]*?\*\//g, ' ')
    .replace(/(^|\s)\/\/.*$/gm, '$1')
    .replace(/(^|[\s"])#.*$/gm, '$1');

const JS_PATTERNS = [
  /\b(?:import|export)\b[^'"`;]*?\bfrom\s*['"`]([^'"`\n]+)['"`]/g,
  /\bimport\s*['"`]([^'"`\n]+)['"`]/g,
  /\b(?:require|import)\s*\(\s*['"`]([^'"`\n]+)['"`]/g
];

const collectJsModules = (content) => {
  const modules = [];
  for (const pattern of JS_PATTERNS) {
    for (const match of content.matchAll(pattern)) modules.push(match[1].trim());
  }
  return modules;
};

const collectPythonModules = (content) => {
  const modules = [];
  const importRegex = /(?:^|[";:])[ \t]*import[ \t]+([\w.]+(?:[ \t]+as[ \t]+\w+)?(?:[ \t]*,[ \t]*[\w.]+(?:[ \t]+as[ \t]+\w+)?)*)/gm;
  for (const match of content.matchAll(importRegex)) {
    for (const part of match[1].split(',')) modules.push(part.trim().split(/\s+/)[0]);
  }
  const fromRegex = /(?:^|[";:])[ \t]*from[ \t]+([\w.]+)[ \t]+import\b/gm;
  for (const match of content.matchAll(fromRegex)) modules.push(match[1]);
  return modules;
};

const extractModules = (content, filePath) => {
  const ext = (filePath.match(/\.[^./\\]+$/) || [''])[0].toLowerCase();
  const code = stripComments(content);
  const python = PYTHON_EXTENSIONS.has(ext);
  const js = JS_EXTENSIONS.has(ext);
  return [
    ...(js || !python ? collectJsModules(code) : []),
    ...(python || !js ? collectPythonModules(code) : [])
  ];
};

const moduleMatchesLibrary = (module, library) => {
  const mod = module.toLowerCase();
  const lib = library.toLowerCase();
  return mod === lib || mod.startsWith(`${lib}/`) || mod.startsWith(`${lib}.`);
};

export const createLibraryDetector = (libraries = DEFAULT_AI_LIBRARIES) => ({
  id: 'libraries',
  analyze({ content, filePath, result }) {
    const modules = extractModules(content, filePath);
    if (!modules.length) return;
    for (const library of libraries) {
      if (modules.some((module) => moduleMatchesLibrary(module, library))) {
        uniqPush(result.aiLibraryMatches, filePath, library);
        result.markAiFile(filePath);
      }
    }
  }
});

'''
s=s[:start]+new+s[end:]
